shots.draw_js:
clearScene();setBig(null);setEq(null);
lamps({y:280,gap:340,items:[
  {label:"界里是 D_TV",sub:"全变差距离",state:"dead"},
  {label:"算法要 KL",sub:"好算、接自然梯度",state:"on"}]});
note("这一步要一个不等式",640,420,"y");
setCap("要把界变成可优化的目标，得先从<b>全变差距离</b>换到 <b>KL 散度</b>。");

clearScene();setEq(null);
setBig("D_TV² ≤ D_KL","讲座就是这么接上去的");
setCap("这一步成立，但它<b>不是 Pinsker</b> —— Pinsker 的右边还要再乘 <b>½</b>。");

clearScene();setBig(null);
setEq("$$D_{TV}(p,q)\\ \\le\\ \\sqrt{\\tfrac12\\,D_{KL}(p\\|q)}\\qquad\\Longrightarrow\\qquad D_{TV}^2\\ \\le\\ \\tfrac12 D_{KL}$$","top");
note("20 万组随机分布未见反例",640,320,"g lg");
note("p→q 时比值趋于 1.0000",640,380,"y lg");
setCap("Pinsker 本尊：<b>½ 在根号里面</b>，而且这个界是<b>紧的</b>。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1],step:760,vals:[0.5,1.0],
  x:380,y:420,w:520,h:170,max:1.2,
  label:function(i){return ["正确","板上"][i];},
  cls:function(i){return i===0?"g":"r";},
  fmt:function(v){return v.toFixed(1)+"·C·KL";}});
note("惩罚项，同一组分布",640,462,"y");
setCap("丢掉 ½ 让惩罚项<b>整整大一倍</b>：(C/2)·KL 变成 C·KL。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"界还成立吗",sub:"成立",state:"on"},
  {label:"松了多少",sub:"一倍",state:"dead"},
  {label:"偏哪一侧",sub:"更保守",state:"on"}]});
note("惩罚估大 = 步子更小",640,420,"g");
setCap("<b>指名反驳</b>：不是 Pinsker，是它的弱化版。界<b>仍然成立</b>，但松一倍。");

clearScene();setBig(null);setEq(null);
lamps({y:270,gap:330,items:[
  {label:"可算的代理 L",sub:"L9 给的",state:"on"},
  {label:"距离惩罚",sub:"上上集给的",state:"on"},
  {label:"单调改进",sub:"这一集拼出来",state:"off"}]});
note("论证只有三行",640,410,"y");
setCap("两块料都齐了。这一集把它们拼成<b>单调改进</b>的保证。");

clearScene();setEq(null);
setBig("有下界就够了","最大化下界，真值自然跟着涨");
setCap("<b>不对</b>。下界可以合法，而最大化它让真值<b>变差</b>。");

clearScene();setBig(null);setEq(null);
axes({l:300,r:1020,t:180,b:440});
curve(fn(function(px){return vy(Vtoy((px-320)/680*0.7));},320,1000,120),"fit");
dots([[vx(0.20),vy(Vtoy(0.20))]],"y",8);
dots([[vx(0.05),vy(Vtoy(0.05))]],"r",8);
note("当前策略",vx(0.20),vy(Vtoy(0.20))-20,"y");
note("下界切在这里",vx(0.05)+52,vy(Vtoy(0.05))+26,"r");
note("真值 V",vx(0.62),vy(1.0)-22,"sm");
setCap("先看一个<b>合法</b>的下界：处处不超过真值，相切点却<b>不在</b>当前策略处。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1],step:800,vals:[0.5292,-0.2705],
  x:380,y:420,w:520,h:160,max:0.65,
  label:function(i){return ["切在当前点","切在别处"][i];},
  cls:function(i){return i===0?"g":"r";},
  fmt:function(v){return (v>0?"+":"")+v.toFixed(4);}});
note("最大化下界后，真值的变化",640,462,"y");
setCap("两个都是<b>合法下界</b>。右边那个把真值从 0.2944 推到了 <b>0.0239</b>。");

clearScene();setBig(null);
setEq("$$M_i(\\pi)=L_{\\pi_i}(\\pi)-C\\cdot D_{KL}^{\\max}(\\pi_i,\\pi)\\ \\ \\Longrightarrow\\ \\ M_i(\\pi_i)=V(\\pi_i)$$","top");
note("因为 KL(π_i,π_i)=0",640,310,"g lg");
note("全部支点就是这一条",640,370,"y lg");
setCap("<b>指名反驳</b>：支点不是「是下界」，是<b>惩罚在 π_i 处归零</b>。");

clearScene();setBig(null);
setEq("$$V_{i+1}\\ \\overset{?}{=}\\ M_i(\\pi_{i+1})$$","top");
note("讲义上是等号",640,300,"r lg");
note("口头说的是「≥」",640,360,"g lg");
setCap("链条推完之后，讲义那一行是<b>等号</b> —— 而<b>讲课时说的是「大于等于」</b>。");

clearScene();setEq(null);
setBig("= 和 ≥ 差不多","反正后面用的是同一条链");
setCap("等号只在<b>一个点</b>成立：π = π_i。离开它就有间隙。");

clearScene();setBig(null);
setEq("$$V(\\pi)\\ \\ge\\ M_i(\\pi)\\quad\\forall\\pi,\\qquad V(\\pi_i)=M_i(\\pi_i)$$","top");
note("下界：处处成立",420,320,"b lg");
note("等号：只在一点",860,320,"g lg");
setCap("「处处是下界」和「在一点相等」是<b>两条</b>性质，不能混成一条。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1,2,3],step:420,vals:[0.0,0.0100,0.0400,0.1764],
  x:330,y:420,w:620,h:160,max:0.21,
  label:function(i){return ["0",".05",".10",".21"][i];},
  cls:function(i){return i===0?"g":(i===3?"r":"y");},
  fmt:function(v){return v.toFixed(4);}});
note("横轴：步长",640,462,"sm");
setCap("间隙 V − M：起点<b>恰好为 0</b>，然后按<b>步长的平方</b>张开。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"板上",sub:"V = M",state:"dead"},
  {label:"实际",sub:"V ≥ M",state:"on"},
  {label:"等号",sub:"只在 π_i",state:"on"}]});
note("间隙按步长平方张开",640,420,"y");
setCap("<b>指名反驳</b>：等号只在 π_i 成立。最大化 M 给的是<b>下界</b>，不是真值。");
